class Solution {
public:
    int minDays(vector<int>& bloomDay, int m, int k) {
        long long need = (long long)m * k;
        if (need > (long long)bloomDay.size()) return -1;

        int lo = 1, hi = 0;
        for (int b : bloomDay) hi = max(hi, b);

        while (lo < hi) {
            int mid = lo + (hi - lo) / 2;
            int bouquets = 0, count = 0;
            for (int b : bloomDay) {
                if (b <= mid) {
                    count++;
                    if (count == k) {
                        bouquets++;
                        count = 0;
                    }
                } else {
                    count = 0;
                }
            }
            if (bouquets >= m) hi = mid;
            else lo = mid + 1;
        }
        return lo;
    }
};
